enum
{
    BA_SPIN,
    BA_TRICK,
    TRICK_EXIT_5 = 40,
    TRICK_EXIT_4 = 47
};

class FEEntityManager
{
    char pad0[404];
    entity* board;
    char pad1[28];
    entity_anim_tree* board_tree;
    char pad2[124];
    int cur_b_anim;

public:
    void BoardAnim(int anim_id, float blend_time, bool loop, float time);
    void BoardPlay(int type, int anim_id, float time);
};

